using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey    = Environment.GetEnvironmentVariable("OPENAI_API_KEY");

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    return 1;
}

// ---------------------------------------------------------------------------
// Tools the agent can call
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (
            [Description("The search query to look up on the web")] string query
        ) =>
        {
            return WebSearcher.SearchAsync(query);
        },
        "web_search",
        "Search the web for information on a topic. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        (
            [Description("A concise title for the note")]  string title,
            [Description("The body text of the note")]     string content
        ) =>
        {
            notebook.Add(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Save a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () =>
        {
            return notebook.ListAll();
        },
        "list_notes",
        "List all research notes that have been saved so far."),
};

// ---------------------------------------------------------------------------
// Build the chat client with automatic function invocation
// ---------------------------------------------------------------------------
IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey)
            .GetChatClient(modelName)
            .AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------
const string SystemPrompt = """
    You are a Research Agent. Your job is to research a topic provided by the
    user using the tools available to you.

    Workflow:
    1. Break the topic into 2-3 sub-questions.
    2. Use web_search to find information for each sub-question.
    3. Use save_note to record the most important findings as you go.
    4. After gathering enough information, use list_notes to review your notes.
    5. Produce a final, well-structured summary of your findings with key
       takeaways and references.

    Always cite the sources you found. Be thorough but concise.
    """;

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════════════╗");
Console.WriteLine("║           🔍 AI Research Agent                  ║");
Console.WriteLine("║  Enter a topic to research, or 'quit' to exit.  ║");
Console.WriteLine("╚══════════════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, SystemPrompt),
        new(ChatRole.User,   $"Please research the following topic: {topic}"),
    };

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\n⏳ Researching… (the agent will search the web and take notes)\n");
    Console.ResetColor();

    ChatResponse response = await client.GetResponseAsync(messages, chatOptions);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine("═══ Research Summary ═══");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine();
}

return 0;

// ═══════════════════════════════════════════════════════════════════════════
// Supporting types
// ═══════════════════════════════════════════════════════════════════════════

/// <summary>Simple in-memory notebook for the agent.</summary>
sealed class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public void Add(string title, string content) => _notes.Add((title, content));

    public void Clear() => _notes.Clear();

    public string ListAll()
    {
        if (_notes.Count == 0)
            return "(no notes saved yet)";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i].Title}\n    {_notes[i].Content}\n");
        return sb.ToString();
    }
}

/// <summary>Web search using the Brave Search API free tier, with a fallback
/// to a DuckDuckGo HTML scrape so the app works without extra API keys.</summary>
static class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(string query)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🔎 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Try Brave Search API if a key is available
            var braveKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");
            if (!string.IsNullOrWhiteSpace(braveKey))
                return await BraveSearchAsync(query, braveKey);

            // Fallback: scrape DuckDuckGo lite
            return await DuckDuckGoSearchAsync(query);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static async Task<string> BraveSearchAsync(string query, string apiKey)
    {
        var url = $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count=5";
        using var req = new HttpRequestMessage(HttpMethod.Get, url);
        req.Headers.Add("X-Subscription-Token", apiKey);
        req.Headers.Accept.Clear();
        req.Headers.Add("Accept", "application/json");

        using var resp = await Http.SendAsync(req);
        resp.EnsureSuccessStatusCode();

        using var doc = JsonDocument.Parse(await resp.Content.ReadAsStringAsync());
        var results = doc.RootElement.GetProperty("web").GetProperty("results");

        var sb = new StringBuilder();
        foreach (var r in results.EnumerateArray().Take(5))
        {
            var title = r.GetProperty("title").GetString();
            var desc  = r.TryGetProperty("description", out var d) ? d.GetString() : "";
            var link  = r.GetProperty("url").GetString();
            sb.AppendLine($"- {title}: {desc} ({link})");
        }
        return sb.Length > 0 ? sb.ToString() : "No results found.";
    }

    private static async Task<string> DuckDuckGoSearchAsync(string query)
    {
        var url = $"https://lite.duckduckgo.com/lite/?q={Uri.EscapeDataString(query)}";
        var html = await Http.GetStringAsync(url);

        // Extract snippets from the lite HTML page
        var sb = new StringBuilder();
        var snippetTag = "<td class=\"result-snippet\">";
        var linkTag    = "<a rel=\"nofollow\" href=\"";
        int pos = 0, count = 0;

        while (count < 5 && (pos = html.IndexOf(snippetTag, pos, StringComparison.Ordinal)) >= 0)
        {
            // Find preceding link
            var linkEnd = html.LastIndexOf("\">", pos, Math.Min(pos, 2000), StringComparison.Ordinal);
            var linkStart = html.LastIndexOf(linkTag, pos, Math.Min(pos, 2000), StringComparison.Ordinal);
            var link = "";
            if (linkStart >= 0 && linkEnd > linkStart)
            {
                linkStart += linkTag.Length;
                link = WebUtility.HtmlDecode(html[linkStart..linkEnd]);
            }

            pos += snippetTag.Length;
            var end = html.IndexOf("</td>", pos, StringComparison.Ordinal);
            if (end < 0) break;

            var snippet = WebUtility.HtmlDecode(
                System.Text.RegularExpressions.Regex.Replace(html[pos..end], "<.*?>", "").Trim());

            if (!string.IsNullOrWhiteSpace(snippet))
            {
                sb.AppendLine($"- {snippet} ({link})");
                count++;
            }
            pos = end;
        }

        return sb.Length > 0 ? sb.ToString() : "No results found.";
    }
}

